/** A Tool's own isolated event count follows actual counter placement, including prevention and KO. */
public final class DamageCounterSuccessTest {
    static final UUID A=GeneratedRuleBatch8Test.A,B=GeneratedRuleBatch8Test.B;
    static final String POLICY="{\"trigger\":\"ON_DAMAGE\",\"from\":\"OPPONENT_ATTACK\",\"activeOnly\":true,\"lethalOnly\":false,\"optional\":false,\"usage\":\"NONE\",\"minimumDamage\":240,\"attackerFamilies\":[\"MEGA_EVOLUTION_EX\"]}";
    static final String COUNTERS="{\"type\":\"damage_counter\",\"target\":\"ATTACKING_POKEMON\",\"amount\":12,\"bind\":\"placed\"}";
    static final String DISCARD="{\"type\":\"conditional\",\"conditions\":[{\"type\":\"BOUND_COUNT\",\"bind\":\"placed\",\"value\":1}],\"effects\":[{\"type\":\"discard_source\"}]}";
    static final Set<PokemonFamily> MEGA=Set.of(PokemonFamily.RULE_BOX,PokemonFamily.EX,PokemonFamily.MEGA_EVOLUTION_EX);
    static void check(boolean b,String s){GeneratedRuleBatch8Test.check(b,s);}
    static UUID active(ServerMatch m,UUID p){return m.activePokemonView(p).pokemonId();}
    static CardInstance hand(ServerMatch m,UUID p,String id){return GeneratedRuleBatch13Test.hand(m,p,id);}
    static TrainerProfile tool(String policy,String body){return BundledCombatData.trainer(JsonParser.parseString("{\"trainerCategory\":\"TOOL\",\"automaticEffects\":[{\"id\":\"bomb\",\"nameZh\":\"反伤成功后弃置\",\"eventPolicy\":"+policy+",\"triggers\":[{\"trigger\":\"ON_DAMAGE\",\"conditions\":[{\"type\":\"NOT\",\"conditions\":[{\"type\":\"IS_FAMILY\",\"target\":\"SELF\",\"pokemon_family\":\"MEGA_EVOLUTION_EX\"}]}],\"effects\":["+body+"]}]}]}").getAsJsonObject(),EffectRegistry.standard());}
    static class Config {TrainerProfile tool=tool(POLICY,COUNTERS+","+DISCARD);int damage=240,hp=500,attackerHp=500;Set<PokemonFamily> attacker=MEGA,host=Set.of();boolean bench=false,copy=false;String extra="";EnergyType weakness,resistance;int resistanceAmount;List<AbilityDefinition> abilities=List.of();}
    static ServerMatch game(Config c){var defs=new ArrayList<CardDefinition>();for(String id:List.of("host","attacker","tool","energy")){boolean p=id.equals("host")||id.equals("attacker");defs.add(new CardDefinition(id,id,p?CardCategory.POKEMON:id.equals("tool")?CardCategory.TRAINER:CardCategory.ENERGY,id.equals("tool")?TrainerCategory.TOOL:TrainerCategory.NONE,"J",Set.of("international"),p,id.equals("energy"),60,Map.of(),EffectSupport.SUPPORTED,null,id.equals("host")?c.host:id.equals("attacker")?c.attacker:Set.of()));}
        var attack=TemporaryReceivedDamageTest.attack("hit",c.damage,EnergyType.COLORLESS,(c.bench?",\"damageTarget\":\"ALL_OPPONENT_BENCH\"":"")+c.extra);var attacks=c.copy?List.of(attack,CopyAttackTest.copier()):List.of(attack);var host=new PokemonProfile(c.hp,0,null,c.weakness,c.weakness==null?0:2,c.resistance,c.resistanceAmount,1,attacks,c.abilities,EnergyType.COLORLESS);var attacker=new PokemonProfile(c.attackerHp,0,null,null,0,null,0,1,attacks,List.of(),EnergyType.COLORLESS);var catalog=new CombatCatalog(Map.of("host",host,"attacker",attacker),Map.of("energy",EnergyType.COLORLESS),Map.of("tool",c.tool));var decks=new ArrayList<List<CardInstance>>();for(UUID owner:List.of(A,B)){var cards=new ArrayList<CardInstance>();for(int i=0;i<60;i++)cards.add(new CardInstance(new UUID(owner.getLeastSignificantBits(),i+1),owner,i<24?(owner.equals(A)?"host":"attacker"):i<28?"tool":"energy"));decks.add(cards);}
        for(int seed=0;seed<1000;seed++){var m=new ServerMatch(A,B,decks.get(0),decks.get(1),GeneratedRuleBatch8Test.RULES,new CardDatabase(defs),catalog,new ServerRandom(seed));OpeningTestSupport.decideOrder(m,A,B);if(List.of(A,B).stream().anyMatch(p->m.privateView(p).hand().stream().filter(x->m.cardDefinition(x.definitionId()).basicPokemon()).count()<2))continue;OpeningTestSupport.complete(m,A,B,1);m.drawCardsByEffect(A,A,28);m.drawCardsByEffect(A,B,28);m.endTurn(A);m.endTurn(B);if(m.privateView(A).hand().stream().anyMatch(x->x.definitionId().equals("tool")))return m;}throw new AssertionError("No counter outcome fixture");}
    public static void main(String[] args){thresholdAndFamilies();prevention();lethal();actualDamage();nonDamageCauses();simultaneous();entryIdentity();copiedActor();multipleTools();contracts();invalid();System.out.println("DamageCounterSuccessTest passed: actual230/240/250 after weakness/resistance/reduction, source/host family, successful/prevented/stale placement, exact Tool discard, simultaneous KO, copy actor, independent Tools, invalid policy and dataflow");}
    static void contracts(){var p=new DamageTriggerPolicy(true,false,false,EnergyTriggerPolicy.Usage.NONE);check(p.minimumDamage()==10&&p.attackerFamilies().isEmpty()&&p.matches(true,10,false),"Old damage policy default changed");var a=tool(POLICY,COUNTERS+","+DISCARD).automaticEffects().getFirst();GeneratedRuleBatch8Test.reject(()->AttackCountBindings.validateAutomatic(a.effectProgram(),EffectTrigger.ON_TURN_END));GeneratedRuleBatch8Test.reject(()->AttackCountBindings.validateManual(new EffectProgram(List.of(new TriggeredEffects(EffectTrigger.ON_CARD_PLAYED,List.of(),a.effectProgram().triggers().getFirst().effects()))),EffectTrigger.ON_CARD_PLAYED));var condition=new ConditionDefinition(ConditionType.BOUND_COUNT,Map.of("bind","placed","value","1"),List.of());GeneratedRuleBatch8Test.reject(()->TriggeredAbilityRules.validateProgram(new EffectProgram(List.of(new TriggeredEffects(EffectTrigger.ON_DAMAGE,List.of(condition),a.effectProgram().triggers().getFirst().effects()))),a.eventPolicy(),null));}
    static CardInstance attach(ServerMatch m,boolean bench){var card=hand(m,A,"tool");m.playTrainer(A,card.instanceId(),bench?m.benchPokemonView(A).getFirst().pokemonId():active(m,A));return card;}
    static void thresholdAndFamilies(){for(String mode:List.of("230","240","250","ORDINARY","LEGACY","HOST_MEGA","HOST_EX","BENCH","DISABLED")){var c=new Config();if(mode.matches("\\d+"))c.damage=Integer.parseInt(mode);if(mode.equals("ORDINARY"))c.attacker=Set.of(PokemonFamily.EX);if(mode.equals("LEGACY"))c.attacker=Set.of(PokemonFamily.EX_LEGACY);if(mode.equals("HOST_MEGA"))c.host=MEGA;if(mode.equals("HOST_EX"))c.host=Set.of(PokemonFamily.EX);if(mode.equals("BENCH"))c.bench=true;var m=game(c);var card=attach(m,c.bench);if(mode.equals("DISABLED"))m.disableToolEffectsByEffect(A,A,active(m,A));m.endTurn(A);var rng=m.randomTranscript();m.attack(B,"hit");boolean fires=Set.of("240","250","HOST_EX").contains(mode);check(m.activePokemonView(B).damage()==(fires?120:0)&&m.privateView(A).discard().contains(card)==fires&&m.randomTranscript().equals(rng),"Counter threshold/family/position wrong "+mode);}}
    static void prevention(){for(String kind:List.of("TRAINER","ABILITY","ANY_CARD")){var m=game(new Config());var card=attach(m,false);m.endTurn(A);var e=EffectRegistry.standard().parse(JsonParser.parseString("{\"type\":\"prevent_effects\",\"target\":\"SELF\",\"source\":\""+kind+"\",\"from\":\"OPPONENT\",\"scope\":\"EFFECTS_ONLY\",\"duration\":\"SOURCE_NEXT_TURN_START\"}").getAsJsonObject());m.executeEffectProgramByRule(B,active(m,B),new EffectProgram(List.of(new TriggeredEffects(EffectTrigger.ON_CARD_PLAYED,List.of(),List.of(e)))),EffectTrigger.ON_CARD_PLAYED);m.attack(B,"hit");boolean fires=kind.equals("ABILITY");check(m.activePokemonView(B).damage()==(fires?120:0)&&m.privateView(A).discard().contains(card)==fires,"Prevented placement still discarded Tool "+kind);}}
    static void lethal(){var c=new Config();c.hp=200;var m=game(c);attach(m,false);m.endTurn(A);m.attack(B,"hit");check(m.activePokemonView(B).damage()==120&&m.phase()==MatchPhase.PRIZE_SELECTION&&m.privateView(B).prizes().size()==6,"Lethal host discarded before Tool reaction or took Prize too early");}

    static String after(String effects){return ",\"triggers\":[{\"trigger\":\"AFTER_ATTACK\",\"effects\":["+effects+"]}]";}
    static void actualDamage(){for(String mode:List.of("WEAK_240","RESIST_230","RESIST_240","REDUCE_230","REDUCE_240","ACCUMULATED")){
        var c=new Config();if(mode.equals("WEAK_240")){c.damage=120;c.weakness=EnergyType.COLORLESS;}
        if(mode.startsWith("RESIST")){c.damage=mode.endsWith("230")?260:270;c.resistance=EnergyType.COLORLESS;c.resistanceAmount=30;}
        if(mode.startsWith("REDUCE")){c.damage=mode.endsWith("230")?250:260;c.abilities=List.of(new AbilityDefinition("reduce","减伤",new AbilityEffect(AbilityEffect.Opcode.PASSIVE_REDUCE_OPPONENT_ATTACK_DAMAGE,20),EffectSupport.SUPPORTED,null,AbilityDefinition.Kind.PASSIVE));}
        if(mode.equals("ACCUMULATED"))c.damage=230;var m=game(c);var card=attach(m,false);if(mode.equals("ACCUMULATED"))m.placeDamageCountersByEffect(A,A,active(m,A),1);m.endTurn(A);m.attack(B,"hit");boolean fires=mode.endsWith("240");check(m.activePokemonView(B).damage()==(fires?120:0)&&m.privateView(A).discard().contains(card)==fires,"Threshold used raw/accumulated damage "+mode);
    }}
    static void nonDamageCauses(){for(String mode:List.of("COUNTERS","DIRECT","POISON","SELF")){
        var c=new Config();c.damage=0;if(mode.equals("COUNTERS"))c.extra=after("{\"type\":\"damage_counter\",\"target\":\"OPPONENT_ACTIVE\",\"amount\":24}");if(mode.equals("DIRECT"))c.extra=after("{\"type\":\"knock_out\",\"target\":\"OPPONENT_ACTIVE\"}");if(mode.equals("SELF"))c.extra=",\"selfDamage\":240";var m=game(c);var card=attach(m,false);
        if(mode.equals("POISON")){m.placeDamageCountersByEffect(A,A,active(m,A),23);m.applySpecialConditionByEffect(A,A,SpecialCondition.POISONED);m.endTurn(A);}else if(mode.equals("SELF"))m.attack(A,"hit");else{m.endTurn(A);m.attack(B,"hit");}
        check(m.activePokemonView(B).damage()==0,"Wrong damage cause triggered counters "+mode);if(!mode.equals("DIRECT"))check(!m.privateView(A).discard().contains(card),"Wrong cause discarded Tool "+mode);
    }}
    static void simultaneous(){var c=new Config();c.hp=200;c.attackerHp=120;var m=game(c);var card=attach(m,false);UUID source=active(m,A),attacker=active(m,B);m.endTurn(A);m.attack(B,"hit");check(m.phase()==MatchPhase.PRIZE_SELECTION&&m.privateView(A).discard().contains(card)&&m.privateView(A).discard().stream().anyMatch(v->v.definitionId().equals("host"))&&m.privateView(B).discard().stream().anyMatch(v->v.definitionId().equals("attacker")),"Both lethal Pokémon must leave in one KO checkpoint");int cap=12;while(m.phase()==MatchPhase.PRIZE_SELECTION&&cap-->0)m.takePrizeAt(m.pendingChoicePlayer(),0);while(m.phase()==MatchPhase.CHOOSE_REPLACEMENT&&cap-->0){UUID p=m.pendingChoicePlayer();m.chooseReplacement(p,m.benchPokemonView(p).getFirst().pokemonId());}check(cap>0&&m.currentPlayer().equals(A)&&m.phase()==MatchPhase.TURN&&m.privateView(A).prizes().size()==5&&m.privateView(B).prizes().size()==5,"Simultaneous reaction repeated prizes/turn progression");}
    static void entryIdentity(){for(String mode:List.of("SWITCH","LEAVE","REENTER")){
        var c=new Config();c.extra=after("{\"type\":\"choice\",\"options\":[{\"type\":\"draw\",\"amount\":1},{\"type\":\"draw\",\"amount\":1}]}");var m=game(c);var card=attach(m,false);UUID original=active(m,B);m.endTurn(A);m.attack(B,"hit");var prompt=m.effectChoicePrompt(B);check(prompt!=null,"Attack text must precede Tool reaction");var f=EventTargetBindingTest.field(m);f.switchActiveByEffect(B,f.benchView(B).getFirst().pokemonId());UUID returned=original;if(!mode.equals("SWITCH")){var removed=f.removePokemonByEffect(B,original);if(mode.equals("REENTER")){f.placeOnBench(B,removed.discardedCards().getFirst());returned=f.printedPokemonView(B,removed.discardedCards().getFirst().instanceId()).pokemonId();}}
        m.chooseEffectOption(B,prompt.resolutionId(),prompt.step(),0);boolean fires=mode.equals("SWITCH");check(m.activePokemonView(B).damage()==0&&m.privateView(A).discard().contains(card)==fires,"Attacker identity fell back to new Active or stale entry "+mode);if(!mode.equals("LEAVE"))check(f.pokemonView(B,returned).damage()==(fires?120:0),"Counter target did not retain exact attacker entry "+mode);
    }}
    static void copiedActor(){for(boolean megaActor:List.of(false,true)){
        var c=new Config();c.copy=true;c.attacker=megaActor?MEGA:Set.of();var m=game(c);var card=attach(m,false);m.endTurn(A);var energy=hand(m,B,"energy");m.attachEnergy(B,energy.instanceId(),active(m,B));var option=m.copyAttackOptions(B,"copy").stream().filter(v->v.attackId().equals("hit")).findFirst().orElseThrow();m.copyAttackWithEnergyDiscards(B,"copy",option.pokemonId(),option.entrySequence(),option.attackId(),List.of(),List.of());check(m.activePokemonView(B).damage()==(megaActor?120:0)&&m.privateView(A).discard().contains(card)==megaActor,"Copy read provider's family instead of actual attacker");
    }}
    static void multipleTools(){for(boolean removeAttacker:List.of(false,true)){
        var c=new Config();c.abilities=List.of(ToolCapacityResolutionTest.capacity(2));var m=game(c);var one=attach(m,false);var two=attach(m,false);m.endTurn(A);m.attack(B,"hit");var order=m.triggerOrderPrompt();check(order!=null&&order.choosingPlayer().equals(A)&&order.entries().size()==2,"Tool order authority or physical source identity lost");GeneratedRuleBatch44Test.assertRejectedAtomic(m,()->m.chooseTriggeredEffect(B,order.id(),order.entries().getFirst().id()));
        if(removeAttacker){var f=EventTargetBindingTest.field(m);UUID old=active(m,B);f.switchActiveByEffect(B,f.benchView(B).getFirst().pokemonId());f.removePokemonByEffect(B,old);}
        DamageTriggeredAbilityTest.finishTriggers(m);check(m.activePokemonView(B).damage()==(removeAttacker?0:240)&&m.privateView(A).discard().contains(one)!=removeAttacker&&m.privateView(A).discard().contains(two)!=removeAttacker,"Independent Tool counts leaked, overwrote or discarded unsuccessful source");GeneratedRuleBatch44Test.assertRejectedAtomic(m,()->m.chooseTriggeredEffect(A,order.id(),order.entries().getFirst().id()));
    }}
    static void invalid(){for(String p:List.of(POLICY.replace("240","230.5"),POLICY.replace("240","\"240\""),POLICY.replace("240","0"),POLICY.replace("240","239"),POLICY.replace("MEGA_EVOLUTION_EX","UNKNOWN"),POLICY.replace("[\"MEGA_EVOLUTION_EX\"]","[]"))){boolean bad=false;try{tool(p,COUNTERS+","+DISCARD);}catch(IllegalArgumentException expected){bad=true;}check(bad,"Invalid policy accepted "+p);}for(String body:List.of(DISCARD+","+COUNTERS,COUNTERS+","+COUNTERS+","+DISCARD,COUNTERS.replace("ATTACKING_POKEMON","SELF")+","+DISCARD,"{\"type\":\"draw\",\"amount\":1,\"bind\":\"placed\"},"+DISCARD)){boolean bad=false;try{tool(POLICY,body);}catch(IllegalArgumentException|IllegalStateException expected){bad=true;}check(bad,"Invalid automatic dataflow accepted "+body);}}
}
